(function() {
  // 配置参数
  const CONFIG = {
    Nt: 32,
    Mt: 20,
    thresholdQ: 18,
    bytesPerElement: 8 // 假设 double precision
  };

  // 状态管理
  const state = {
    q: 10,
    isOverflow: false
  };

  // DOM 元素缓存
  const elements = {
    slider: null,
    qValue: null,
    matrixCols: null,
    totalElements: null,
    memoryEst: null,
    status: null,
    warning: null,
    canvas: null,
    resetBtn: null
  };

  // 初始化
  function init() {
    cacheElements();
    bindEvents();
    updateVisualization();
  }

  // 缓存 DOM 元素
  function cacheElements() {
    const container = document.getElementById('chap-3-bottleneck');
    elements.slider = container.querySelector('#q-slider');
    elements.qValue = container.querySelector('#q-value');
    elements.matrixCols = container.querySelector('#matrix-cols');
    elements.totalElements = container.querySelector('#total-elements');
    elements.memoryEst = container.querySelector('#memory-est');
    elements.status = container.querySelector('#memory-status');
    elements.warning = container.querySelector('#overflow-warning');
    elements.canvas = container.querySelector('#memory-chart');
    elements.resetBtn = container.querySelector('#reset-btn');
  }

  // 绑定事件
  function bindEvents() {
    if (!elements.slider) return;

    elements.slider.addEventListener('input', handleSliderChange);
    elements.resetBtn.addEventListener('click', handleReset);

    // 键盘支持
    elements.slider.addEventListener('keydown', (e) => {
      let val = parseInt(elements.slider.value);
      if (e.key === 'ArrowLeft') val = Math.max(parseInt(elements.slider.min), val - 1);
      if (e.key === 'ArrowRight') val = Math.min(parseInt(elements.slider.max), val + 1);
      elements.slider.value = val;
      handleSliderChange();
    });
  }

  // 滑块处理
  function handleSliderChange() {
    state.q = parseInt(elements.slider.value);
    updateVisualization();
  }

  // 重置处理
  function handleReset() {
    state.q = 10;
    elements.slider.value = 10;
    updateVisualization();
  }

  // 更新可视化
  function updateVisualization() {
    const q = state.q;
    const qSquared = q * q;
    // 矩阵维度：(Nt*Mt) x (q^2)
    // 元素总数 = Nt * Mt * q^2 * q^2 = Nt * Mt * q^4
    // 注意：论文中公式 (7) 维度为 (NtMt) x (qazqel)^2
    // 元素数量 = Nt * Mt * (q^2)^2 = Nt * Mt * q^4
    const totalElements = CONFIG.Nt * CONFIG.Mt * Math.pow(qSquared, 2);
    const memoryBytes = totalElements * CONFIG.bytesPerElement;

    state.isOverflow = q > CONFIG.thresholdQ;

    // 更新文本显示
    elements.qValue.textContent = q;
    elements.matrixCols.textContent = qSquared.toLocaleString();
    elements.totalElements.textContent = formatScientific(totalElements);
    elements.memoryEst.textContent = formatBytes(memoryBytes);

    // 更新状态指示器
    if (state.isOverflow) {
      elements.status.textContent = '状态：危险 (内存溢出)';
      elements.status.classList.add('danger');
      elements.warning.classList.add('active');
    } else {
      elements.status.textContent = '状态：安全';
      elements.status.classList.remove('danger');
      elements.warning.classList.remove('active');
    }

    // 绘制图表
    drawChart();
  }

  // 绘制图表
  function drawChart() {
    const ctx = elements.canvas.getContext('2d');
    const width = elements.canvas.width;
    const height = elements.canvas.height;
    const padding = 40;

    // 清空画布
    ctx.clearRect(0, 0, width, height);

    // 坐标轴
    ctx.beginPath();
    ctx.strokeStyle = '#bdc3c7';
    ctx.lineWidth = 1;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 标签
    ctx.fillStyle = '#7f8c8d';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('候选点数量 (q)', width / 2, height - 10);

    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.fillText('相对内存占用 (log 尺度)', 0, 0);
    ctx.restore();

    // 绘制曲线
    ctx.beginPath();
    ctx.strokeStyle = state.isOverflow ? '#e74c3c' : '#00b894';
    ctx.lineWidth = 3;

    const maxQ = 30;
    const currentQ = state.q;

    // 计算缩放比例
    // Y 轴使用对数刻度以展示指数增长
    const getMaxVal = () => {
      const q = maxQ;
      const qSquared = q * q;
      return CONFIG.Nt * CONFIG.Mt * Math.pow(qSquared, 2);
    };
    const maxVal = getMaxVal();

    const plotWidth = width - 2 * padding;
    const plotHeight = height - 2 * padding;

    for (let qPlot = 4; qPlot <= currentQ; qPlot++) {
      const qSq = qPlot * qPlot;
      const val = CONFIG.Nt * CONFIG.Mt * Math.pow(qSq, 2);

      // 对数映射
      const logVal = Math.log10(val);
      const logMax = Math.log10(maxVal);
      const logMin = Math.log10(CONFIG.Nt * CONFIG.Mt * Math.pow(16, 2)); // q=4

      const x = padding + (qPlot - 4) / (maxQ - 4) * plotWidth;
      const y = height - padding - ((logVal - logMin) / (logMax - logMin)) * plotHeight;

      if (qPlot === 4) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // 绘制当前点
    const qSq = currentQ * currentQ;
    const val = CONFIG.Nt * CONFIG.Mt * Math.pow(qSq, 2);
    const logVal = Math.log10(val);
    const logMax = Math.log10(maxVal);
    const logMin = Math.log10(CONFIG.Nt * CONFIG.Mt * Math.pow(16, 2));

    const curX = padding + (currentQ - 4) / (maxQ - 4) * plotWidth;
    const curY = height - padding - ((logVal - logMin) / (logMax - logMin)) * plotHeight;

    ctx.beginPath();
    ctx.arc(curX, curY, 6, 0, Math.PI * 2);
    ctx.fillStyle = state.isOverflow ? '#e74c3c' : '#00b894';
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.stroke();

    // 绘制阈值线
    const thresholdQ = CONFIG.thresholdQ;
    const tSq = thresholdQ * thresholdQ;
    const tVal = CONFIG.Nt * CONFIG.Mt * Math.pow(tSq, 2);
    const tLogVal = Math.log10(tVal);
    const tY = height - padding - ((tLogVal - logMin) / (logMax - logMin)) * plotHeight;

    ctx.beginPath();
    ctx.strokeStyle = '#f39c12';
    ctx.setLineDash([5, 5]);
    ctx.moveTo(padding, tY);
    ctx.lineTo(width - padding, tY);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = '#f39c12';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText('q=18 临界点', width - padding - 5, tY - 5);
  }

  // 工具函数：科学计数法
  function formatScientific(num) {
    if (num < 10000) return num.toLocaleString();
    const exp = Math.floor(Math.log10(num));
    const mantissa = num / Math.pow(10, exp);
    return mantissa.toFixed(2) + 'e+' + exp;
  }

  // 工具函数：字节格式化
  function formatBytes(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    return (bytes / (1024 * 1024 * 1024)).toFixed(1) + ' GB';
  }

  // 启动
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
